let currentIndex = 0;
const track = document.getElementById('sliderTrack');
const cards = document.querySelectorAll('.slider-track .card');
const totalCards = cards.length;
let visibleCards = 4;
let cardWidth = cards[0].offsetWidth + 24; // width + gap

function updateVisibleCards() {
  if (window.innerWidth <= 576) visibleCards = 1;
  else if (window.innerWidth <= 992) visibleCards = 2;
  else visibleCards = 4;
  
  cardWidth = cards[0].offsetWidth + 24;
}

function slideTestimonials(direction) {
  updateVisibleCards();
  const maxIndex = totalCards - visibleCards;
  
  currentIndex += direction;
  
  // Infinite loop - forward
  if (currentIndex >= maxIndex) {
    currentIndex = 0;
    track.style.transition = 'none';
    track.style.transform = `translateX(0)`;
    setTimeout(() => {
      track.style.transition = 'transform 0.5s ease';
    }, 10);
    return;
  }
  
  // Infinite loop - backward
  if (currentIndex < 0) {
    currentIndex = maxIndex - 1;
    track.style.transition = 'none';
    track.style.transform = `translateX(-${currentIndex * cardWidth}px)`;
    setTimeout(() => {
      track.style.transition = 'transform 0.5s ease';
      currentIndex = maxIndex - 2;
      track.style.transform = `translateX(-${currentIndex * cardWidth}px)`;
    }, 10);
    return;
  }
  
  track.style.transform = `translateX(-${currentIndex * cardWidth}px)`;
}

// Auto-slide
let autoSlide = setInterval(() => slideTestimonials(1), 5000);

// Pause on hover
const slider = document.querySelector('.testimonial-slider');
slider.addEventListener('mouseenter', () => clearInterval(autoSlide));
slider.addEventListener('mouseleave', () => {
  autoSlide = setInterval(() => slideTestimonials(1), 5000);
});

// Handle resize
let resizeTimeout;
window.addEventListener('resize', () => {
  clearTimeout(resizeTimeout);
  resizeTimeout = setTimeout(() => {
    updateVisibleCards();
    const maxIndex = totalCards - visibleCards;
    if (currentIndex > maxIndex - 1) {
      currentIndex = maxIndex - 1;
    }
    track.style.transition = 'none';
    track.style.transform = `translateX(-${currentIndex * cardWidth}px)`;
    setTimeout(() => {
      track.style.transition = 'transform 0.5s ease';
    }, 10);
  }, 200);
});

// Initial setup
updateVisibleCards();